// === Tab: mySketch ===
// Attractive force / repulsive force model
var num = 1000;
var vx = new Array(num);
var vy = new Array(num);
var x = new Array(num);
var y = new Array(num);
var ax = new Array(num);
var ay = new Array(num);

var magnetism = 10; //Strength of attractive force It becomes repulsive force when it is minus.
var radius = 1 ; //Radius of drawing circle
var gensoku = .95; // Decelerate particle movement

function setup(){
  createCanvas(windowWidth,windowHeight);
  noStroke(); 
  fill(0);
  ellipseMode(RADIUS);
  background(0);
  blendMode(ADD);

  for(var i =0; i< num; i++){
    x[i] = random(width);
    y[i] = random(height);
    vx[i] = 0;
    vy[i] = 0;
    ax[i] = 0;
    ay[i] = 0;
  }
}


function draw(){
	//magnestism = random(-30, 30);
	background(0);
  fill(0,0,0);
  rect(0,0,width,height);

  for(var i=0; i<num; i++){
    var distance = dist(touchX, touchY, x[i], y[i]); //dist(x1,y1,x2,y2) Function for finding the distance between two points
    //Acceleration is inversely proportional to the square of the distance from the center of gravity.
    if(distance > 3){ //If you are too close to the mouse, do not update the acceleration
      ax[i] = magnetism * (touchX - x[i]) / (distance * distance); 
      ay[i] = magnetism * (touchY - y[i]) / (distance * distance);
    }
    vx[i] += ax[i]; // Increase speed vx by ax per frame.
    vy[i] += ay[i]; // Increase speed vy by ay per frame.

    vx[i] = vx[i]*gensoku;
    vy[i] = vy[i]*gensoku;

    x[i] += vx[i];  // Move forward by vx pixels per frame.
    y[i] += vy[i];  // Move forward by vy pixels per frame.

    var v = dist(0,0,vx[i],vy[i]); // Find velocity from X and Y components of velocity
    var r = map(v, 0, 5, 0, 255); //Calculate colors according to speed
    var g = map(v, 0,5, 64, 255);
    var b = map(v, 0,5, 128, 255);
    fill(r, g, b, 32);
    ellipse(x[i],y[i],radius,radius);
  }

}

